widget.solution:
def turnover(positions):
    # mean of |positions[t] - positions[t - 1]| over t = 1 .. n - 1
    if len(positions) < 2:
        return 0.0
    changes = [abs(positions[t] - positions[t - 1]) for t in range(1, len(positions))]
    return sum(changes) / len(changes)

def net_pnl(positions, returns, cost_bp):
    # one net P&L per day: position times return, minus cost on the change
    out, prev = [], 0.0
    for p, r in zip(positions, returns):
        out.append(p * r - cost_bp / 10000 * abs(p - prev))
        prev = p
    return out

