widget.solution:
def break_even_cost_bp(positions, returns):
    if sum(net_pnl(positions, returns, 0)) <= 0:
        return 0.0
    lo, hi = 0.0, 10000.0
    for _ in range(100):
        mid = (lo + hi) / 2
        if sum(net_pnl(positions, returns, mid)) > 0:
            lo = mid
        else:
            hi = mid
    return round((lo + hi) / 2, 2)

def smooth_positions(raw, band):
    cur, out = 0.0, []
    for x in raw:
        if abs(x - cur) > band:
            cur = x
        out.append(cur)
    return out
